class Solution:
    def findKthPositive(self, arr: List[int], k: int) -> int:
        lo, hi = 0, len(arr) - 1
        while lo < hi:
            mid = hi - (hi - lo) // 2
            # mid = lo + (hi - lo) // 2
            missing = arr[mid] - mid - 1
            if missing < k:
                lo = mid
            else:
                hi = mid - 1

        if arr[lo] - lo - 1 >= k:
            return k
        else:
            return k + lo + 1

class Solution:
    def findKthPositive(self, arr: List[int], k: int) -> int:
        counter = 0
        index = 0
        while (k > 0):
            counter += 1
            if index < len(arr) and arr[index] == counter:
                index += 1
            else:
                k -= 1
        return counter

primes = [2, 3, 5, 7]

def is_prime(n):
    if n < 2:
        return False
    m = int(n ** .5) + 1
    for p in primes:
        if p >= m: break
        if not n % p:
            return False
    q, d = primes[-1], 4 if (n + 1) % 6 else 2
    while q < m:
        q, d = q + d, 4 - d
        if is_prime(q):
            primes.append(q)
            if not n % q:
                return False
    return True
